input.command:
mkdir -p src test && cat > package.json <<'EOF'
{
  "name": "set-proto",
  "version": "0.1.0",
  "description": "Set the prototype of an object at runtime",
  "main": "src/index.js",
  "types": "src/index.d.ts",
  "files": [
    "src"
  ],
  "scripts": {
    "test": "node --test"
  },
  "engines": {
    "node": ">=18"
  },
  "license": "MIT"
}
EOF
cat > src/index.js <<'EOF'
'use strict';

/**
 * Set the prototype of `obj` to `proto` and return `obj`.
 *
 * Uses the standard `Object.setPrototypeOf` (ES2015), which is available in
 * every supported Node.js version and all modern browsers, so no polyfill or
 * third-party dependency is needed.
 *
 * @template T
 * @param {T} obj
 * @param {object | null} proto
 * @returns {T}
 */
function setPrototypeOf(obj, proto) {
  return Object.setPrototypeOf(obj, proto);
}

module.exports = setPrototypeOf;
module.exports.setPrototypeOf = setPrototypeOf;
EOF
cat > src/index.d.ts <<'EOF'
declare function setPrototypeOf<T>(obj: T, proto: object | null): T;
declare namespace setPrototypeOf {
  export { setPrototypeOf };
}
export = setPrototypeOf;
EOF
cat > test/index.test.js <<'EOF'
'use strict';

const test = require('node:test');
const assert = require('node:assert');
const setPrototypeOf = require('..');

test('sets the prototype and returns the same object', () => {
  const proto = { greet() { return 'hi'; } };
  const obj = {};
  const result = setPrototypeOf(obj, proto);
  assert.strictEqual(result, obj);
  assert.strictEqual(Object.getPrototypeOf(obj), proto);
  assert.strictEqual(obj.greet(), 'hi');
});

test('accepts null', () => {
  const obj = setPrototypeOf({}, null);
  assert.strictEqual(Object.getPrototypeOf(obj), null);
});

test('throws on invalid prototype', () => {
  assert.throws(() => setPrototypeOf({}, 42), TypeError);
});

test('named export matches default', () => {
  assert.strictEqual(setPrototypeOf.setPrototypeOf, setPrototypeOf);
});
EOF
cat > .gitignore <<'EOF'
node_modules/
*.log
transcript.jsonl
EOF
cat > README.md <<'EOF'
# set-proto

Set the prototype of an object at runtime.

```js
const setPrototypeOf = require('set-proto');

const obj = setPrototypeOf({}, { greet() { return 'hi'; } });
obj.greet(); // 'hi'
```

Built on the standard `Object.setPrototypeOf`, so it has no dependencies and
works on all supported Node.js versions and modern browsers.

## Development

```sh
npm test
```
EOF
npm test 2>&1 | tail -12

